registeredPlugins.pluginDef:
// ═══════════════════════════════════════════════════════════════
//  QR Code 3D Plugin — My 3D Gifts Pro
//  Link / URL → 3D printable QR Code (raised boxes)
//  v5 — added Design CARD button link
// ═══════════════════════════════════════════════════════════════

var plugin = {

  name: "QR Code 3D Generator",

  controls: [
    { key: "qrText",     label: "Link (URL)",          type: "text",     default: "https://my3dgifts.com" },
    { key: "moduleSize", label: "Module Size (mm)",    type: "range",    min: 1,  max: 20,  step: 0.5, default: 5 },
    { key: "qrHeight",   label: "QR Box Height (mm)",  type: "range",    min: 1,  max: 20,  step: 0.5, default: 5 },
    { key: "errorLevel", label: "Error Correction",    type: "select",   options: ["L","M","Q","H"], default: "M" },
    { key: "addBorder",  label: "Border (Quiet Zone)", type: "checkbox", default: true },
    { key: "designCard", label: "Design CARD",         type: "button",   href: "https://my3dgifts.com/3d/qr%20design.html" }
  ],

  _libLoading: false,
  _libCallbacks: [],

  // ── Load qrcode-generator (Kazuhiko Arase, MIT) ──────────────
  _loadQRLib: function(callback) {
    if (typeof window !== "undefined" && typeof window.qrcode === "function") {
      callback(); return;
    }
    plugin._libCallbacks.push(callback);
    if (plugin._libLoading) return;
    plugin._libLoading = true;

    var s = document.createElement("script");
    // Real qrcode-generator (returns matrix via isDark). NOT qrcodejs.
    s.src = "https://cdn.jsdelivr.net/npm/qrcode-generator@1.4.4/qrcode.min.js";
    s.onload = function() {
      plugin._libLoading = false;
      var cbs = plugin._libCallbacks.slice();
      plugin._libCallbacks = [];
      for (var i = 0; i < cbs.length; i++) try { cbs[i](); } catch(e) { console.error(e); }
    };
    s.onerror = function() {
      plugin._libLoading = false;
      console.error("[QR Plugin] Failed to load qrcode-generator library");
    };
    document.head.appendChild(s);
  },

  // ── Build 3D geometry from QR matrix ─────────────────────────
  _build3D: function(obj, params, THREE) {
    var modSize    = parseFloat(params.moduleSize) || 5;
    var qrH        = parseFloat(params.qrHeight)  || 5;
    var text       = (params.qrText || "https://my3dgifts.com").trim();
    var errorLevel = params.errorLevel || "M";
    var addBorder  = params.addBorder !== false;

    // typeNumber 0 = auto-detect smallest version
    var qr;
    try {
      qr = window.qrcode(0, errorLevel);
      qr.addData(text);
      qr.make();
    } catch(e) {
      console.error("[QR Plugin] encode error:", e);
      return;
    }

    var qrSize = qr.getModuleCount();
    var border = addBorder ? 4 : 0;
    var totalW = (qrSize + border * 2) * modSize;
    var cx = totalW / 2, cy = totalW / 2;

    // Collect dark module boxes
    var boxes = [];
    for (var row = 0; row < qrSize; row++) {
      for (var col = 0; col < qrSize; col++) {
        if (qr.isDark(row, col)) {
          boxes.push({
            x: (col + border) * modSize,
            y: (qrSize - 1 - row + border) * modSize  // flip Y so QR reads upright
          });
        }
      }
    }

    var n = boxes.length;
    if (n === 0) { console.warn("[QR Plugin] no modules generated"); return; }

    var posArr = new Float32Array(n * 8 * 3);
    var idxArr = new Uint32Array(n * 36);
    var vi = 0, ii = 0;

    function addBox(bx, by) {
      var x0=bx-cx, x1=bx+modSize-cx, y0=by-cy, y1=by+modSize-cy, z0=0, z1=qrH;
      var c=[[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0],
             [x0,y0,z1],[x1,y0,z1],[x1,y1,z1],[x0,y1,z1]];
      var b=vi;
      for(var k=0;k<8;k++){posArr[(b+k)*3]=c[k][0];posArr[(b+k)*3+1]=c[k][1];posArr[(b+k)*3+2]=c[k][2];}
      var f=[[0,2,1],[0,3,2],[4,5,6],[4,6,7],[0,1,5],[0,5,4],
             [2,3,7],[2,7,6],[0,4,7],[0,7,3],[1,2,6],[1,6,5]];
      for(var fi=0;fi<f.length;fi++){idxArr[ii++]=b+f[fi][0];idxArr[ii++]=b+f[fi][1];idxArr[ii++]=b+f[fi][2];}
      vi+=8;
    }

    for (var i = 0; i < boxes.length; i++) addBox(boxes[i].x, boxes[i].y);

    var geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.Float32BufferAttribute(posArr, 3));
    geo.setIndex(new THREE.BufferAttribute(idxArr, 1));
    geo.computeVertexNormals();

    obj.geometry.dispose();
    obj.geometry = geo;

    if (typeof window !== "undefined" && window.updateLivePreview) window.updateLivePreview();
    console.log("[QR Plugin] size="+qrSize+" modules="+n+" text="+text);
  },

  // ── Entry point ──────────────────────────────────────────────
  apply: function(obj, params, THREE) {
    if (!obj || !obj.geometry) return;
    plugin._loadQRLib(function() {
      plugin._build3D(obj, params, THREE);
    });
  },

  reset: function(obj, THREE) {}
};

return plugin;
